module Mcp
  # The tool list the model reads (generated by maquina:mcp), gathered from
  # every module in app/models/mcp/tools/: by file name, then in each module's
  # declaration order, so tools/list is the same on every call.
  #
  # Each module there owns its tools: DEFINITIONS (frozen JSON Schema
  # 2020-12, written in plain English for the model, units stated),
  # WRITE_TOOLS (names that need the write scope) and ADMIN_ONLY. maquina:mcp_tool
  # writes to tools/app.rb; maquina:solid_errors and the other operational
  # generators each write their own file.
  module ToolDefinitions
    TOOLS_GLOB = "app/models/mcp/tools/*.rb"

    def self.modules
      Dir[Rails.root.join(TOOLS_GLOB)].sort.map do |path|
        "Mcp::Tools::#{File.basename(path, ".rb").camelize}".constantize
      end
    end

    # Admin-only modules read operational data across every account, not the
    # user's own: only someone with backstage access (User#backstage_access?,
    # the backstage.emails list) and MCP enabled sees them. An account's admin
    # role is not enough. For everyone else they do not exist.
    def self.visible_modules(user)
      modules.reject { |mod| mod::ADMIN_ONLY && !(user.backstage_access? && Mcp.enabled_for?(user)) }
    end

    def self.for(user)
      visible_modules(user).flat_map { |mod| mod::DEFINITIONS }
    end

    # The visible module that declares the tool, or nil: an unknown name and a
    # hidden one look the same.
    def self.owner(name, user)
      visible_modules(user).find { |mod| mod::DEFINITIONS.any? { |definition| definition[:name] == name } }
    end
  end
end
